INSERT INTO `abouts` (`id`, `name`, `description`, `image`) VALUES
(1, 'Empowering Health with Innovation Since 2013', '<p>At Aqualife, we&#39;ve been delivering cutting-edge water filtration systems since 2013, providing homes, businesses, and industries across Indonesia with the pure, safe water they deserve. Our core values of innovation, sustainability, and health drive us to offer high-performance systems backed by exceptional customer service and fast after-sales support. With over 5,000 satisfied customers, we&#39;re committed to making clean water a necessity for every home and business.</p>\r\n', '1830037124img-law.png');
INSERT INTO `about_details` (`id`, `title`, `subtitle`, `icon`) VALUES
(2, 'Rated Highly for Exceptional Service', 'From Consultation to Installation', 'thumb-up');
INSERT INTO `adventages` (`id`, `title`, `description`, `images`, `category_id`) VALUES
(2, 'Perbedaan Nyata: Sebelum & Sesudah', 'Perbedaan Nyata: Sebelum & Sesudah', '526030240announcement.png', 4),
(3, 'Use Aqualife Produk', 'Use Aqualife Produk', '1987928875announcement.png', 5),
(4, 'Use Gallon', 'Use Gallon', '1115400914announcement.png', 5),
(6, 'See the Aqualife Luma Difference', '<b>Prevent Scale, Rust, and Odor—Protect Your Health and Appliances</b>\r\nUntreated water often contains minerals, iron, and other impurities that lead to scale buildup, rust, and stains on household appliances. With Aqualife CleanFlow, your water is purified leaving your faucets, showers, and fixtures clean, rust-free, and longer-lasting. Protect your family\'s health and your appliances with every drop.', '1855653562img-law.png', 7);
INSERT INTO `banner_headers` (`id`, `title`, `subtitle`, `description`, `images`, `category_id`) VALUES
(3, 'WATER TREATMENT PLANT', 'Whole House Water Filtration System', 'Aqualife Luma effectively removes contaminants such as sediments, chemicals, heavy metals, iron, manganese, and unpleasant odors providing clean, safe, and high-quality water throughout your home.', '937846379announcement.png', 3),
(4, 'Water Softener For Your Home', 'Goodbye Hard Water, Hello Aqualife Luma Water Softener!', 'The Aqualife Luma water softening system brings you a host of benefits, from softer skin and hair to cleaner, brighter clothes. Say goodbye to stains and scale buildup, and protect your household appliances from hard water damage, extending their lifespan.', '137137597announcement.png', 4),
(5, ' Aqualife Reverse Osmosis System', 'Quality You Can Taste', 'Aqualife\'s advanced Reverse Osmosis (RO) system removes up to 99% of bacteria, viruses, chlorine, and heavy metals—delivering crystal-clear, great-tasting water on demand.', '1411636722announcement.png', 5),
(6, 'asdf', 'asdf', 'asdf', '858969234img-law.png', 6),
(7, 'dzs', 'dsf', 'sdf', '60379926img-law.png', 7);
INSERT INTO `benefits` (`id`, `category_id`, `images`, `title`, `description`) VALUES
(1, '[\"3\"]', '1591019680Screenshot', 'Improving Water Quality', 'Eliminates unpleasant odors (such as chlorine and rotten egg smell), discoloration, and harmful chemicals, giving your water a clean, fresh taste.'),
(2, '[\"3\"]', '883152785announcement.png', 'Cleaner and Safer Water', 'Removes bacteria, viruses, iron, manganese, sediments, and harmful contaminants, providing safer and healthier water for your family.'),
(3, '[\"3\"]', '1494479388announcement.png', 'Efficient and Cost Effective', 'Saves money by reducing your reliance on bottled water, providing a cost-effective long-term solution.'),
(4, '[\"4\"]', '565492382announcement.png', 'Prevents Scale Buildup', 'Protects pipes, faucets, and appliances from scale buildup caused by hard water, extending their lifespan.'),
(5, '[\"4\"]', '1263178777announcement.png', 'Softer Skin and Hair', 'Helps retain moisture in your skin and hair, reducing dryness and irritation caused by hard water.'),
(6, '[\"4\"]', '1442140340announcement.png', 'Improves Detergent Efficiency', 'Soft water allows detergents to work more effectively, leading to cleaner clothes, dishes, and surfaces with less detergent.'),
(7, '[\"5\"]', '623289399announcement.png', '99% Contaminant Removal', 'Eliminates bacteria, viruses, chlorine and heavy metals.'),
(8, '[\"5\"]', '1368418366announcement.png', 'Better Taste & Odor-Free', 'Filters out unpleasant flavors and smells.'),
(9, '[\"3\"]', '1732493428announcement.png', 'Health & Hydration', 'Supports overall well-being with pure drinking water.'),
(10, '[\"7\"]', '1610923293img-law.png', 'adsf', 'asdf'),
(11, '[\"7\"]', '409376470avatar-default.png', 'adsf', 'sdf');
