INSERT INTO `did_you_knows` (`id`, `title`, `description`, `images`, `category_id`) VALUES
(2, 'Did You Know ?', 'Water hardness varies across regions in Indonesia. Studies show that up to 63% of households in certain areas use water with hardness levels exceeding safe standards. Hard water can significantly impact the quality of water in your home and increase maintenance costs.', '219041505announcement.png', 4),
(3, 'How Reverse Osmosis Transforms Contaminated Water Into Purity', 'As water enters the pipe, it carries impurities such as bacteria, viruses, and particles. The membrane acts as a barrier, allowing only clean water molecules to pass through, while trapping contaminants and pollutants. This process ensures that the water exiting the system is filtered and safe to use, effectively removing various pollutants and producing clear, clean water.', '170087332announcement.png', 5),
(4, 'Di Indonesia, lebih dari 50% air bersih yang digunakan oleh masyarakat sebenarnya terkontaminasi bak', 'The 2020 Household Drinking Water Quality Study\r\nmenemukan bahwa 7 dari 10 rumah tangga di Indonesia mengonsumsi air minum yang terkontaminasi bakteri Escherichia coli (E. coli).\r\n\r\nMany Refill Drinking Water Depots do not Disclose The\r\nsumber air yang mereka gunakan. Kurangnya transparansi ini meningkatkan risiko kontaminasi dari limbah atau zat berbahaya lainnya.', '2023056415announcement.png', 3);
INSERT INTO `faqs` (`id`, `title`, `description`, `created_at`) VALUES
(2, 'Apa itu Filtrasi Air?', 'Filtrasi air adalah proses menghilangkan atau mengurangi konsentrasi partikel, termasuk partikel tersuspensi, parasit, bakteri, alga, virus, dan jamur, serta zat terlarut dan biologis lainnya dari air.', '2025-08-05 07:41:26'),
(3, 'Apa itu Sistem Filtrasi Air?', 'Sistem filtrasi air adalah perangkat atau serangkaian perangkat yang digunakan untuk melakukan filtrasi air. Sistem ini dapat bervariasi dari kendi sederhana hingga sistem seluruh rumah yang kompleks.', '2025-08-05 14:41:39'),
(5, 'sfdf', 'sdgf', '2025-08-09 21:26:48');
