INSERT INTO `overviews` (`id`, `title`, `subtitle`, `description`, `images`, `category_id`) VALUES
(2, 'WHAT IS WATER TREATMENT', 'Why Do I Need a Water Treatment System?', 'Our Aqualife Luma water treatment systems eliminate harmful substances such as chlorine, heavy metals, sediment, bacteria, iron, manganese, and unpleasant odors, ensuring your water is clean and safe for drinking, cooking, and bathing. With CleanFlow, you protect your health, improve water quality, and extend the lifespan of your plumbing and household appliances.', '152858550announcement.png', 3),
(3, 'WHAT IS HARD WATER', 'Where Can It Be Seen?', 'Hard water contains high levels of minerals like calcium and magnesium, which can cause scaling, discoloration, and the deterioration of household appliances. It can also lead to dry skin, dull hair, and stained laundry.', '1431423357announcement.png', 4),
(4, 'Aqualife Reverse Osmosis System', 'Quality You Can Taste', 'Aqualife\'s advanced Reverse Osmosis (RO) system removes up to 99% of bacteria, viruses, chlorine, and heavy metals—delivering crystal-clear, great-tasting water on demand.', '647835660announcement.png', 5),
(6, 'bh', 'jbj', 'jn', '1394244152avatar-default.png', 7);
