INSERT INTO `why_choose_us` (`id`, `title`, `description`, `images`, `category_id`) VALUES
(2, 'Fresh Water, Long Lasting Equipment1', 'The Aqualife Luma Water Softener is the perfect solution for your home or business. By eliminating excess minerals like calcium and magnesium, it prevents scale buildup in pipes, appliances, and machinery, ensuring they last longer. Softer water also improves skin and hair health, enhances the cleaning power of soap and detergent, and reduces maintenance costs. Whether you need it for your home or business, Aqualife Luma keeps your water fresh, your equipment running efficiently, and your environment cleaner and healthier.', '1421837337announcement.png', 4),
(3, 'On Demand Purity', 'Instant access to filtered water, no boiling, no bottles', '1088239514announcement.png', 5),
(4, 'Peace Of Mind', 'Industry leading membrane technology for your family\'s health', '33975035announcement.png', 5),
(5, 'Save Money & Planet', 'Say goodbye to single-use plastics and high utility bills.', '180461495announcement.png', 5);
